const fs = require('fs');
const zlib = require('zlib');
const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');

// Parse ZIP manually to find word/document.xml
let offset = 0;
while (offset < buf.length - 4) {
  const sig = buf.readUInt32LE(offset);
  if (sig !== 0x04034b50) break; // local file header
  const compMethod = buf.readUInt16LE(offset + 8);
  const compSize = buf.readUInt32LE(offset + 18);
  const uncompSize = buf.readUInt32LE(offset + 22);
  const fnameLen = buf.readUInt16LE(offset + 26);
  const extraLen = buf.readUInt16LE(offset + 28);
  const fname = buf.slice(offset + 30, offset + 30 + fnameLen).toString();
  const dataStart = offset + 30 + fnameLen + extraLen;
  const dataEnd = dataStart + compSize;

  if (fname === 'word/document.xml') {
    let xml;
    if (compMethod === 0) {
      xml = buf.slice(dataStart, dataEnd).toString();
    } else {
      xml = zlib.inflateRawSync(buf.slice(dataStart, dataEnd)).toString();
    }
    // Extract text from XML: get content between <w:t> tags, respect <w:p> as paragraphs
    let result = '';
    // Split by paragraph
    const paras = xml.split(/<\/w:p>/);
    for (const p of paras) {
      const texts = [];
      const re = /<w:t[^>]*>([^<]*)<\/w:t>/g;
      let m;
      while ((m = re.exec(p)) !== null) {
        texts.push(m[1]);
      }
      if (texts.length > 0) {
        result += texts.join('') + '\n';
      }
    }
    console.log(result.trim());
    break;
  }
  offset = dataEnd;
}
